(window.RYADOM_I18N = window.RYADOM_I18N || {})["ja"] = {"strings":{"Разделы":"セクション","Сегодня":"今日","Мой дневник":"マイ日記","Места":"場所","Игры":"ゲーム","Практики":"プラクティス","Обо мне":"わたしについて","Ты можешь идти в своём темпе.":"自分のペースで大丈夫です。","Здесь нет правильных ответов и обязательных серий дней.":"正解も、連続記録のノルマもありません。","Пространство для себя":"自分のための場所","Профиль":"プロフィール","Как ты сегодня?":"今日はどんな気分ですか？","Можно честно. Начнём с того, что есть сейчас.":"正直で大丈夫。今あるところから始めましょう。","С чего начать":"どこから始める？","Поговорить":"話す","Своими словами, без правил":"自分の言葉で、ルールなし","Потренировать разговор":"会話を練習する","Начальник, мама, отказ, извинение":"上司、母、断る、謝る","Подобрать практику":"プラクティスを選ぶ","Подходящую сейчас":"今に合うもの","Рядом":"Ryadom","На твоей стороне":"あなたの味方","Напиши, что происходит…":"今どうしているか書いてください…","Написать сообщение":"メッセージを書く","Продиктовать сообщение":"音声で入力","Отправить":"送信","Озвучивать ответы":"返信を読み上げる","На сегодня":"今日のひとこと","Достаточно одного маленького шага":"小さな一歩で十分です","Не нужно исправлять весь день целиком.":"一日全部を立て直さなくていいんです。","Твоё пространство":"あなたの場所","Разговоры и отметки сохраняются только на этом устройстве.":"会話と記録はこの端末にだけ保存されます。","Последняя отметка":"最後の記録","Пока нет":"まだありません","Открыть дневник →":"日記を開く →","✦ ПРАКТИКА ДНЯ":"✦ 今日のプラクティス","После трудного разговора":"つらい会話のあとで","4–6 минут · пройти →":"4〜6分 · はじめる →","Только о тебе и твоём состоянии":"あなたとあなたの状態だけ","Разговоры, ощущения и места, в которых прошёл твой день. Игровые истории хранятся отдельно.":"一日の会話、気持ち、過ごした場所。ゲームの物語は別に保存されます。","Календарь дня ↓":"カレンダー ↓","7 дней":"7日間","30 дней":"30日間","Как сегодня внутри?":"今日の心の中はどうですか？","Четыре отдельные отметки от 0 до 4. Это твои ощущения, а не медицинская оценка.":"0〜4の4つの記録。医学的な評価ではなく、あなたの感じ方です。","Тревога":"不安","совсем нет":"まったくない","очень сильно":"とても強い","Грусть":"悲しさ","Беспокойство":"落ち着かなさ","Спокойствие":"落ち着き","Что запомнилось сегодня?":"今日、心に残ったことは？","(необязательно)":"（任意）","Можно отмечать раз в день. Сегодняшнюю отметку можно изменить.":"記録は1日1回。今日の分は変更できます。","Сохранить отметку":"記録を保存","Сильная тревога":"強い不安","Нет отметок":"記録なし","Сильная грусть":"強い悲しさ","Много спокойствия":"落ち着きが多い","Как менялось состояние":"状態の移り変わり","Каждая точка — твоя отметка за день. Пропуски не считаются нулём.":"点は1日ごとの記録です。記録のない日はゼロになりません。","Пока нет точек на графике. Поставь первую отметку выше.":"グラフにはまだ点がありません。上で最初の記録をどうぞ。","0 — совсем нет":"0 — まったくない","4 — очень сильно":"4 — とても強い","Что можно заметить":"気づけること","После трёх отметок здесь появится короткое наблюдение. Пропущенные дни не учитываются.":"3回記録すると、ここに短い気づきが表示されます。記録のない日は数えません。","Что помогает именно тебе":"あなたに効くこと","Когда ты попробуешь практику и оценишь её, здесь появятся твои наблюдения.":"プラクティスを試して評価すると、ここに気づきが表示されます。","Стереть дневник":"日記を消去","Календарь дня":"カレンダー","Предыдущий месяц":"前の月","Следующий месяц":"次の月","Пн":"月","Вт":"火","Ср":"水","Чт":"木","Пт":"金","Сб":"土","Вс":"日","Синяя точка — разговор, зелёная — место. Цвет дня — настроение; другие точки — отметка ощущений. Игровые события сюда не попадают.":"青い点は会話、緑は場所。日の色は気分、ほかの点は気持ちの記録。ゲームの出来事は表示されません。","Пока нет записей за этот день. Можно добавить место, которое тебе запомнилось.":"この日の記録はまだありません。印象に残った場所を追加できます。","Места этого дня":"この日の場所","Пока пусто":"まだ空です","Добавь посещённое место. Приложение не отслеживает перемещения автоматически.":"訪れた場所を追加してください。アプリが移動を自動で追跡することはありません。","＋ Добавить место":"＋ 場所を追加","Места записываешь только ты. Они остаются на этом устройстве и не привязаны к игровому прогрессу.":"場所を記録するのはあなただけ。この端末に残り、ゲームの進行とは関係ありません。","Дневник хранится только на этом устройстве. Посещённые места добавляешь только ты; автоматического отслеживания перемещений нет.":"日記はこの端末にだけ保存されます。訪れた場所を追加するのはあなただけで、位置の自動追跡はありません。","Место для этого момента":"今の気分に合う場所","Куда под настроение?":"気分に合わせてどこへ行く？","Иногда помогает сменить обстановку. Выбери, чего хочется сейчас, и посмотри места поблизости.":"環境を変えると楽になることも。今の気分を選んで、近くの場所を見てみましょう。","Какое настроение?":"どんな気分？","☁ Грустно":"☁ 悲しい","◌ Тревожно":"◌ 不安","♡ Романтично":"♡ ロマンチック","✷ Весело":"✷ 楽しい","✿ Спокойно":"✿ 穏やか","◇ Хочется нового":"◇ 新しいこと","☕ Устало":"☕ 疲れた","↗ Хочется общения":"↗ 人と話したい","Можно выбрать настроение, а потом указать город или разрешить определить примерное местоположение.":"気分を選んでから、都市名を入れるか、おおよその位置情報を許可してください。","Где искать?":"どこで探す？","Геолокация запрашивается только по нажатию и не записывается в дневник. Поиск по названию города показывает места около его центра.":"位置情報はタップしたときだけ求め、日記には保存しません。都市名で探すと中心部付近が表示されます。","⌖ Рядом со мной":"⌖ 近くで","Или город / район":"または都市・地区","Например, Тбилиси":"例：京都","Найти":"探す","Выбери настроение и место поиска.":"気分と探す場所を選んでください。","Место найдётся":"きっと見つかります","Выбери настроение и нажми «Рядом со мной» или введи город. Любимые места из дневника появятся здесь первыми.":"気分を選んで「近くで」を押すか、都市名を入力してください。日記のお気に入りが先に表示されます。","Порядок: сначала любимые, затем подходящие места по расстоянию. Рейтинги и популярность в соцсетях пока не доступны — мы не подменяем их количеством посещений.":"並び順：お気に入りが先、その後は距離順。評価やSNSでの人気はまだなく、訪問回数で代用することもしません。","Моё: что я люблю":"わたしの好きなもの","Работает без интернета. Если поиск мест недоступен, подсказки берутся отсюда и из раздела «Обо мне».":"オフラインでも使えます。検索できないときは、ここと「わたしについて」から提案します。","Пока пусто. Добавь любимое место, блюдо или занятие: подсказки станут точнее.":"まだ空です。好きな場所・料理・過ごし方を追加すると、提案が的確になります。","Что добавить":"追加するもの","Еда":"食べ物","Место":"場所","Занятие":"過ごし方","например: кофейня у реки":"例：川沿いのカフェ","Название или описание":"名前や説明","Добавить":"追加","Новые места: данные участников OpenStreetMap через Photon. Сведения могут быть неполными.":"新しい場所：Photon 経由の OpenStreetMap 協力者のデータ。情報が不完全な場合があります。","Интерактивные истории":"インタラクティブな物語","Игры про жизнь":"人生のゲーム","Герои, разговоры и решения, после которых меняется история.":"物語を変える登場人物、会話、選択。","Сюжетная игра · одна неделя":"ストーリーゲーム · 1週間","Тихий город: неделя до ответа":"静かな町：返事までの1週間（ロシア語）","Письмо о работе в другом городе, мама, папа, подруга и восемь слотов времени. На всё не хватит — и каждая встреча оставит след.":"別の町からの仕事のオファー、母、父、友人、そして8つの時間枠。全部はできない——会うたびに何かが残ります。","Одна неделя, восемь слотов, пять единиц сил":"1週間、8つの枠、5つの体力","Начать историю →":"物語をはじめる →","Тренажёры разговоров":"会話トレーニング","Квесты, где выбор слов меняет ход разговора. Опираются на известные методики общения.":"言葉の選び方で会話が変わるクエスト。よく知られたコミュニケーション手法に基づきます。現在はロシア語のみ。","КВЕСТ · 6 ШАГОВ · 2 СТИЛЯ":"クエスト · 6ステップ · 2スタイル","Разговор с начальником":"上司との会話","Трудная обратная связь. Неудачный ответ оставляет на месте, удачный пускает дальше и называет приём, на котором он держится.":"厳しいフィードバック。うまくない返答では進めず、良い返答なら先へ進み、使った技法がわかります。","Тренажёр разговора":"会話トレーニング","КВЕСТ · 5 ШАГОВ · 2 СТИЛЯ":"クエスト · 5ステップ · 2スタイル","Сказать «нет» коллеге":"同僚に「ノー」と言う","Отказать на просьбу о выходных так, чтобы не поссориться: пауза, спокойное «нет», держать решение, предложить своё.":"週末の頼みをけんかせずに断る：間を取る、落ち着いた「ノー」、決めたことを守る、自分の案を出す。","Границы на работе":"仕事での境界線","Разговор с мамой о границах":"母と境界線について話す","Сохранить близость и право решать самому: признать чувства, сказать «я», договориться о понятном ритме.":"近さと自分で決める権利を保つ：気持ちを認める、「わたし」で話す、わかりやすいペースを決める。","Границы в семье":"家族との境界線","Извиниться и починить":"謝って関係を直す","Подвели близкого человека. Как извиниться конкретно, выслушать и предложить, что исправите.":"身近な人をがっかりさせたとき。具体的に謝り、話を聞き、どう償うかを伝える。","Конфликт и примирение":"対立と仲直り","Попросить о помощи":"助けを求める","Попросить так, чтобы человеку было легко и согласиться, и отказать: конкретно, без извинений, с взаимностью.":"相手が引き受けるのも断るのも楽なように頼む：具体的に、謝りすぎず、お返しも添えて。","Просьбы":"お願い","Разговор о деньгах":"お金の話","Обсудить неравные общие расходы без обвинений: факты, отражение, пропорциональное решение, срок сверки.":"不公平な共通の出費を責めずに話す：事実、相手の言葉を返す、割合に応じた解決、見直しの日。","Деньги и близкие":"お金と身近な人","Сказать, что тебе нужно":"必要なことを伝える","Попросить больше времени вместе, не обвиняя: мягкий старт, «я»-сообщение, валидация, небольшой эксперимент.":"責めずに一緒の時間を増やしたいと伝える：やわらかな切り出し、「わたし」メッセージ、受けとめ、小さな試み。","Отношения":"人間関係","Отказать другу":"友人に断る","Отказаться от поездки так, чтобы дружба не пострадала: пауза, тёплое «нет», повтор решения, альтернатива.":"友情を傷つけずに旅行を断る：間を取る、あたたかい「ノー」、決めたことをくり返す、代わりの案。","Дружба и границы":"友情と境界線","Другие сюжетные направления · 12 коротких историй":"ほかの物語 · 短編12本（ロシア語）","Границы без ссоры":"けんかせずに境界線を","Учиться говорить о своих возможностях и желаниях.":"できることと望むことを話す練習。","ИГРАТЬ · 2 ДНЯ":"プレイ · 2日","Тревога и неопределённость":"不安と不確かさ","Отличать риск от тревожных предположений.":"本当のリスクと不安な想像を見分ける。","ИГРАТЬ · 4 ГЛАВЫ":"プレイ · 4章","Внутренний критик":"心の中の批判者","Находить более честный и бережный внутренний голос.":"より正直でやさしい心の声を見つける。","Сложный разговор":"むずかしい会話","Тренировать фразы и слушать ответ собеседника.":"言い方を練習し、相手の返事を聞く。","Когда нет сил":"力が出ないとき","Планировать восстановление без гонки продуктивности.":"生産性を競わずに回復を計画する。","Свои решения":"自分で決める","Замечать чужие ожидания и выбирать свой шаг.":"人の期待に気づき、自分の一歩を選ぶ。","Отношения с собой":"自分との関係","Собирать опоры, которые не зависят от оценки других.":"人の評価に左右されない支えを集める。","Одиночество и близость":"孤独とつながり","Искать посильные способы установить контакт.":"無理なくつながる方法を探す。","Работа и выгорание":"仕事と燃え尽き","Замечать нагрузку и договариваться о границах.":"負担に気づき、境界線を話し合う。","Потеря и перемены":"喪失と変化","Давать место чувствам и искать поддержку.":"気持ちに場所をつくり、支えを探す。","Тело и забота":"からだとケア","Замечать сигналы тела без оценивания внешности.":"見た目を評価せず、からだのサインに気づく。","Отделять свои потребности от требований других.":"自分の必要と人の要求を分ける。","Первая история — полноценная, на том же движке, что «Тихий город». Остальные одиннадцать — короткие зарисовки на четыре сцены, их предстоит переписать так же.":"最初の物語は完成版で、「静かな町」と同じエンジンです。残り11本は4場面の短いスケッチで、同じように書き直す予定です。","Инструменты на каждый день":"毎日のための道具","Библиотека практик":"プラクティス集","Выбирай то, что подходит моменту. Можно пропустить любой шаг.":"今に合うものを選んでください。どのステップも飛ばせます。","ПРАКТИКА В ФОКУСЕ · 4–6 МИНУТ":"注目のプラクティス · 4〜6分","Когда слова ещё звучат в голове. Сначала найдём опору, затем разберём событие и выберем один посильный шаг.":"言われたことがまだ頭に響いているとき。まず支えを見つけ、出来事を整理して、できる一歩を選びます。","01 · Опора":"01 · 支え","02 · Ясность":"02 · 整理","03 · Действие":"03 · 行動","Попробовать практику →":"やってみる →","Подходит сейчас":"今に合うもの","Без сравнения":"比べない","Заметь мысль «другие справляются лучше». Замени её на конкретный факт о сегодняшней нагрузке.":"「ほかの人はもっとうまくやれている」という考えに気づき、今日の負担についての具体的な事実に置きかえましょう。","Работа":"仕事","Рабочая граница":"仕事での線引き","Назови реалистичный срок и то, что потребуется, чтобы уложиться. Не обещай невозможного.":"現実的な締め切りと、それに間に合わせるのに必要なことを伝えましょう。無理な約束はしないで。","Злость":"怒り","Граница одной фразой":"一言で線を引く","Попробуй фразу: «Мне важно обсудить задачу, когда мы сможем говорить спокойно». Подстрой её под себя.":"この言い方を試してみて：「落ち着いて話せるときに、この件を話し合いたいです」。自分に合うように変えてください。","Маршруты: несколько шагов подряд":"ルート：いくつかのステップを続けて","После трудного разговора с начальником":"上司とのつらい会話のあとで","практика":"プラクティス","Вернуться в момент":"今に戻る","Отметить":"チェック","После критики":"批判されたあと","Факты после встречи":"会議のあとの事実","тренажёр":"トレーニング","Ответ начальнику":"上司への返事","Научиться говорить «нет»":"「ノー」と言えるように","Пауза перед ответом":"返事の前のひと呼吸","Право на нет":"断る権利","Сложный разговор с близким":"身近な人とのむずかしい会話","Сначала услышать":"まず聞く","Я-сообщение":"「わたし」メッセージ","Близость и границы":"近さと境界線","Помириться после ссоры":"けんかのあとの仲直り","Моя часть":"自分の側の責任","Тёплое сообщение":"あたたかいメッセージ","Когда совсем нет сил":"まったく力が出ないとき","Базовые нужды":"基本的な欲求","Минимальный шаг":"いちばん小さな一歩","Просьба о помощи":"助けを求める","Тихая прогулка":"静かな散歩","Спокойный вечер":"穏やかな夜","Вечерняя граница":"夜の線引き","Выгрузить мысли":"考えを書き出す","Переход ко сну":"眠りへの切り替え","Поиск практики":"プラクティスを探す","Например: тревога, начальник, сон…":"例：不安、上司、睡眠…","Все":"すべて","Перегрузка":"過負荷","Сон":"睡眠","Нет сил":"力が出ない","Мысли":"考え","Мягкое дыхание":"やさしい呼吸","Замедлиться и почувствовать опору.":"ペースを落とし、支えを感じる。","Переключить внимание на то, что вокруг.":"まわりのものに注意を向ける。","Слова и границы":"言葉と境界線","Когда чужие слова задели слишком сильно.":"人の言葉がつらく刺さったとき。","Разложить по полочкам":"整理する","Отделить событие от мыслей о нём.":"出来事と、それについての考えを分ける。","Тёплая фраза":"あたたかい一言","Поддержать себя без требования быть сильнее.":"もっと強くなれと求めずに、自分を支える。","Смена обстановки":"場所を変える","Вода, движение или немного воздуха.":"水、からだを動かす、少し外の空気。","Три опоры":"3つの支え","Оглянись и назови три устойчивых предмета рядом. Почувствуй стопы на полу. Сделай один удобный выдох.":"まわりを見て、近くにある動かないものを3つ挙げましょう。足が床についているのを感じて、楽に一度息を吐きます。","Длинный выдох":"長く吐く","Вдохни естественно, затем выдохни немного медленнее. Повтори несколько раз без задержки дыхания и без усилия.":"自然に吸って、少しゆっくり吐きます。息を止めたり力んだりせず、何度かくり返しましょう。","Проверка фактов":"事実を確かめる","Запиши: что я знаю точно, что предполагаю и что могу уточнить. Не требуй от себя немедленного решения.":"書き出しましょう：確実に知っていること、思い込みかもしれないこと、確かめられること。すぐに結論を出さなくて大丈夫です。","План на ближайший час":"この1時間の計画","Выбери одно безопасное и выполнимое действие на ближайший час. Остальное пока оставь на потом.":"この1時間でできる、安全なことをひとつ選びましょう。ほかのことは後回しで大丈夫。","Найди цвет":"色を探す","Выбери цвет и найди вокруг пять предметов этого цвета. Верни внимание к комнате, когда мысли ускоряются.":"色をひとつ決めて、まわりからその色のものを5つ探しましょう。考えが速くなったら、部屋に注意を戻します。","Контакт с поверхностью":"触れている面を感じる","Заметь, как кресло или пол поддерживают тело. Опиши про себя три точки контакта.":"椅子や床がからだを支えているのを感じましょう。触れている3か所を心の中で言葉にします。","Язык":"言語","Язык интерфейса, практик и разговора. Квесты и сюжетные игры пока на русском.":"画面・プラクティス・会話の言語。クエストとストーリーゲームは現在ロシア語のみです。","Только то, что рассказано тобой":"あなたが話したことだけ","Что обо мне известно":"わたしについて知られていること","Чтобы «Рядом» мог подсказать, куда сходить, что поесть и что поможет, ему нужно знать тебя. Здесь видно всё, что он помнит. Записи остаются только на этом устройстве: любую можно удалить.":"Ryadom がどこへ行くか、何を食べるか、何が助けになるかを提案するには、あなたを知る必要があります。覚えていることはすべてここに表示されます。記録はこの端末だけに残り、どれでも削除できます。","Использовать в разговоре и подсказках":"会話と提案に使う","Подтянуть из любимых мест":"お気に入りの場所から取り込む","Что люблю есть":"好きな食べもの","блюда, кухня, вкусы":"料理、ジャンル、味","например: тёплый суп, кофе с булочкой":"例：あたたかいスープ、パンとコーヒー","Где мне хорошо":"心地よい場所","места и обстановка":"場所と雰囲気","например: набережная, тихая библиотека":"例：川辺の遊歩道、静かな図書館","Как люблю проводить время":"好きな過ごし方","занятия и ритм":"過ごし方とリズム","например: долгая прогулка, кино вечером":"例：長い散歩、夜の映画","Что помогает, когда тяжело":"つらいときに助けになること","то, что правда работает":"本当に効くもの","например: горячий чай, музыка в наушниках":"例：熱いお茶、ヘッドホンで音楽","С кем мне легко":"一緒にいて楽な人","люди и формат общения":"人と付き合い方","например: с сестрой, один на один":"例：姉と、二人きりで","Чего лучше избегать":"避けたいこと","что выматывает или раздражает":"疲れること、イライラすること","например: шумные места, спешка":"例：にぎやかな場所、急かされること","Стереть всё, что обо мне записано":"わたしについての記録をすべて消去","Дневник, места и игровой прогресс — отдельные данные: их очистка здесь не затрагивается.":"日記・場所・ゲームの進行は別のデータです。ここで消しても影響しません。","Моя активность за 7 дней":"7日間のアクティビティ","Считается только на этом устройстве и никуда не отправляется. Помогает понять, чем ты пользуешься.":"この端末だけで数え、どこにも送られません。よく使う機能がわかります。","Пока нет данных.":"まだデータがありません。","Скопировать сводку":"まとめをコピー","Сбросить счётчики":"カウンターをリセット","Данные и конфиденциальность":"データとプライバシー","Всё, что ты вводишь, остаётся на этом устройстве. Здесь можно посмотреть, что хранится, сохранить копию или удалить всё.":"入力したものはすべてこの端末に残ります。ここで保存内容の確認、コピーの保存、すべての削除ができます。","Другие данные приложения":"その他のアプリデータ","Сохранить копию файлом":"ファイルにコピーを保存","Скопировать текст":"テキストをコピー","Восстановить из файла":"ファイルから復元","Файл с данными":"データファイル","Восстановить из вставленного текста":"貼り付けたテキストから復元","Удалить все мои данные":"すべてのデータを削除","Как приложение обращается с данными":"アプリのデータの扱い","Где хранятся.":"保存場所。","В памяти браузера или приложения на этом устройстве. Учётных записей и серверной базы нет. Если очистить данные браузера или сменить устройство без копии, записи пропадут.":"この端末のブラウザまたはアプリの保存領域です。アカウントもサーバーのデータベースもありません。ブラウザのデータを消したり、コピーなしで端末を変えたりすると記録は失われます。","Что передаётся наружу.":"外部に送られるもの。","Поиск мест: текст запроса и, если разрешишь, примерные координаты уходят в сервисы карт OpenStreetMap (Photon, Nominatim). Режим с сервером и ИИ, если он подключён: текст твоих сообщений уходит на сервер и к ИИ-провайдеру, чтобы получить ответ. Голосовой ввод и озвучка используют службы устройства.":"場所の検索：検索語と、許可した場合はおおよその座標が OpenStreetMap の地図サービス（Photon、Nominatim）に送られます。サーバー・AIモードを接続している場合：返信を得るためにメッセージの本文がサーバーとAI事業者に送られます。音声入力と読み上げは端末のサービスを使います。","Что приложение не делает.":"アプリがしないこと。","Не следит за перемещениями, не продаёт и не показывает рекламу, не ставит диагнозов. Счётчики использования считаются только на этом устройстве.":"移動を追跡せず、データを売らず、広告を出さず、診断もしません。利用回数はこの端末だけで数えます。","Важно.":"大切なこと。","Приложение не является медицинским изделием и не заменяет помощь специалиста. Это прототип, и тексты ещё не проверены психологом.":"このアプリは医療機器ではなく、専門家の支援の代わりにはなりません。試作版で、文章はまだ心理の専門家の確認を受けていません。","Показать вводную ещё раз":"はじめの説明をもう一度","Если сейчас очень тяжело или есть риск навредить себе, позвони по номеру 112 или обратись к близкому человеку.":"今とてもつらい、または自分を傷つけてしまいそうなときは、救急番号（日本では119）に電話するか、身近な人に連絡してください。","Дневник":"日記","Закрыть":"閉じる","Маленький шаг":"小さな一歩","Практика после трудного разговора":"つらい会話のあとのプラクティス","Прежде чем начать":"はじめる前に","Коротко о том, как устроено «Рядом».":"Ryadom のしくみを簡単に。","Что это":"これは何？","Цифровой помощник для разговора о состоянии, тренировки трудных разговоров и подбора мест. Это не врач и не психолог, диагнозов не ставит и не заменяет специалиста.":"気持ちを話したり、むずかしい会話を練習したり、場所を探したりするためのデジタルの相手です。医師や心理士ではなく、診断もせず、専門家の代わりにはなりません。","Где данные":"データはどこに","Дневник, разговоры и «Обо мне» хранятся только на этом устройстве. Ты можешь выгрузить их или удалить всё в разделе «Обо мне».":"日記・会話・「わたしについて」はこの端末だけに保存されます。「わたしについて」で書き出しや全削除ができます。","Что уходит наружу":"外部に送られるもの","Поиск мест отправляет запрос карте (OpenStreetMap). Если подключён режим с сервером и ИИ, текст сообщения уходит на сервер для ответа. Голосовой ввод использует службы твоего устройства.":"場所の検索では、検索語が地図サービス（OpenStreetMap）に送られます。サーバー・AIモードを接続していると、返信のためにメッセージが送られます。音声入力は端末のサービスを使います。","Если тяжело всерьёз":"本当につらいとき","При мыслях о вреде себе или другим обратись к человеку рядом или по номеру 112. Приложение подскажет, но срочную помощь оно не заменит.":"自分や他人を傷つけたい考えがあるときは、近くの人に頼るか、救急番号（日本では119）に電話してください。アプリは道を示せますが、緊急の助けの代わりにはなりません。","Понятно, продолжить":"わかりました、続ける","Рядом — маленькие шаги к себе":"Ryadom — 自分へ向かう小さな一歩","Тревожно":"不安","Сегодняшняя отметка сохранена. Её можно изменить.":"今日の記録を保存しました。変更できます。","дней с отметкой 3–4 из 4":"4段階中3〜4の日","Добавить в любимые":"お気に入りに追加","Любимое место":"お気に入りの場所","Изменить":"編集","Удалить":"削除","Разговоры за этот день":"この日の会話","Удалить разговоры за этот день":"この日の会話を削除","Из «Обо мне»:":"「わたしについて」より：","добавлено мной":"自分で追加","из разговора":"会話から","Отметки состояния":"状態の記録","Отметка о вводном экране":"はじめの画面を表示済み","Разговоры":"会話","Дневник настроения":"気分の日記","Посещённые места":"訪れた場所","Профиль «Обо мне»":"「わたしについて」プロフィール","Меньше новостей":"ニュースを減らす","Если поток новостей усиливает тревогу, отложи его на 15 минут и выбери конкретное время для проверки.":"ニュースで不安が強まるなら、15分離れて、見る時間を決めましょう。","Кому можно написать":"連絡できる人","Выбери человека, которому можно коротко написать: «Мне тревожно. Можешь побыть на связи?»":"短いメッセージを送れる人を選びましょう：「不安なんだ。少しやりとりしてくれる？」","Назвать чувство":"気持ちに名前をつける","Скажи себе: «Мне сейчас грустно». Не объясняй и не исправляй это чувство в ту же секунду.":"「今、悲しい」と自分に言ってみましょう。すぐに説明したり直したりしなくていいんです。","Мягкий день":"やさしい一日","Составь минимальный план: еда, вода, один обязательный шаг и один посильный источник тепла.":"最低限の計画を：食事、水、どうしても必要なことひとつ、無理のない心のぬくもりをひとつ。","Память о хорошем":"よかったことを思い出す","Вспомни один спокойный момент за последнюю неделю. Запиши детали: место, свет, звук.":"この1週間の穏やかな瞬間をひとつ思い出し、場所・光・音を書き出しましょう。","Тёплый контакт":"あたたかなつながり","Напиши близкому человеку одну честную фразу о своём состоянии, если хочется быть услышанной или услышанным.":"聞いてほしいときは、身近な人に今の気持ちを正直に一文だけ送ってみましょう。","Разрешить паузу":"休むことを許す","Поставь таймер на пять минут. Можно просто посидеть, не превращая отдых в задачу.":"5分間のタイマーをかけて、ただ座っていてもいいんです。休むことを課題にしないで。","Небольшая забота":"ちょっとしたケア","Выбери одну бережную вещь: плед, душ, чай или прогулку. Отметь, стало ли хоть немного легче.":"やさしいことをひとつ選びましょう：毛布、シャワー、お茶、散歩。少しでも楽になったか確かめて。","Свет и воздух":"光と空気","Если удобно, подойди к окну или выйди на несколько минут. Заметь температуру воздуха и положение тела.":"できれば窓辺へ行くか、数分外に出てみましょう。空気の温度とからだの姿勢に気づいて。","Прежде чем отвечать, отойди от переписки на пару минут. Спроси себя, какой результат нужен от ответа.":"返信する前に数分やりとりから離れて、返信で何を得たいのか自分に聞いてみましょう。","Где злость в теле":"怒りはからだのどこに？","Заметь, где в теле сейчас напряжение. Расслабь челюсть или плечи, если это приятно, не подавляя чувство.":"今、からだのどこに力が入っているか感じてみて。心地よければ、あごや肩をゆるめましょう。気持ちを押さえこまなくていいんです。","Черновик без отправки":"送らない下書き","Напиши резкий ответ в заметке, которую не отправишь. Затем выдели одну просьбу, которую действительно хочешь донести.":"送らないメモに、きつい返事を書きましょう。そのあと、本当に伝えたいお願いをひとつだけ取り出します。","Отойти от экрана":"画面から離れる","Положи телефон и сделай несколько шагов. Возвращайся к разговору, когда сможешь выбрать тон.":"スマホを置いて少し歩きましょう。口調を選べるようになったら会話に戻ります。","Что задело":"何が刺さったか","Раздели на две строки: что произошло и какую важную потребность это затронуло.":"2行に分けて：何が起きたか、それがどんな大切な気持ちに触れたか。","Безопасная разрядка":"安全に発散する","Сильно прижми стопы к полу на несколько секунд, затем отпусти. Повтори комфортно, без боли.":"数秒間、足の裏で床をぐっと押してから力を抜きます。痛くない範囲で心地よくくり返しましょう。","Право отложить":"先送りにする権利","Если нет срочности, назначь время ответа позже. Тебе не обязательно решать конфликт в пике эмоций.":"急ぎでなければ、返事の時間を後に決めましょう。感情のピークで対立を解決しなくていいんです。","Одна задача":"ひとつの作業","Выпиши всё, что давит. Обведи одну задачу, которую можно начать за десять минут.":"気になっていることを全部書き出し、10分で始められる作業をひとつ丸で囲みましょう。","Пять процентов":"5パーセント","Спроси: что сделает ближайший час на пять процентов легче? Выбери один маленький шаг.":"「この1時間を5％楽にするには？」と問いかけて、小さな一歩をひとつ選びましょう。","Снять лишнее":"よけいなものを減らす","Посмотри на список дел и вычеркни, перенеси или попроси помощи хотя бы с одним пунктом.":"やることリストを見て、少なくとも1つは消すか、延ばすか、助けを頼みましょう。","Перерыв между делами":"作業のあいだの休憩","Перед новой задачей сделай паузу: вода, взгляд вдаль, несколько спокойных движений.":"次の作業の前にひと休み：水を飲む、遠くを見る、ゆっくり体を動かす。","Проверка тела":"からだのチェック","Заметь голод, жажду, усталость и напряжение. Начни с самой простой телесной потребности.":"空腹、のどの渇き、疲れ、緊張に気づき、いちばん簡単なからだの欲求から満たしましょう。","Достаточно на сегодня":"今日はここまで","Сформулируй критерий «достаточно хорошо» для одной задачи. Остановись, когда он достигнут.":"ひとつの作業について「これで十分」の基準を決め、達したら終わりにしましょう。","Попросить ясности":"はっきりさせてもらう","Если запрос размытый, уточни срок, приоритет и ожидаемый результат у того, кто его дал.":"頼まれたことがあいまいなら、締め切り・優先度・求める結果を頼んだ人に確かめましょう。","Тихое окно":"静かな時間","На десять минут отключи необязательные уведомления и займись одним делом.":"10分間、急がない通知を切って、ひとつのことだけをしましょう。","За некоторое время до сна снизь яркость экрана и выбери спокойное занятие без цели «уснуть немедленно».":"寝る少し前に画面を暗くして、「すぐ眠る」ことを目標にしない静かな過ごし方を選びましょう。","Запиши незавершённые дела и один следующий шаг к каждому. Вернуться к списку можно завтра.":"やり残したことと、それぞれの次の一歩を書き出しましょう。リストには明日戻れば大丈夫。","Комфортная поза":"楽な姿勢","Устрой тело удобнее и мягко замечай точки опоры. Дыхание оставь естественным.":"からだを楽な姿勢にして、支えられている場所をやさしく感じましょう。呼吸は自然なままで。","Тихие звуки":"静かな音","Прислушайся к трём звукам вокруг. Не оценивай их, просто отмечай появление и исчезновение.":"まわりの音を3つ聴いてみましょう。評価せず、聞こえてきて消えていくのをただ感じます。","Без борьбы со сном":"眠りと戦わない","Если не спится, напомни себе: отдых тоже ценен. Выбери спокойное занятие и вернись в постель, когда захочется.":"眠れないときは、休むことにも価値があると自分に言い聞かせて。静かなことをして、眠くなったら布団に戻りましょう。","Назначь момент, после которого рабочие сообщения подождут до завтра, если это возможно.":"できれば、仕事の連絡は明日まで待ってもらう時間を決めましょう。","Мягкое завершение":"やさしい締めくくり","Назови одну вещь, которую удалось сделать сегодня. Даже очень маленькую.":"今日できたことをひとつ挙げましょう。とても小さなことでも。","Спокойное утро":"穏やかな朝","Подготовь одну мелочь для утра: одежду, стакан воды или список первого дела.":"朝のために小さな準備をひとつ：服、コップ一杯の水、最初にやることのメモ。","Составь фразу: «Когда произошло…, мне было… Мне хотелось бы…».":"文を作ってみましょう：「…が起きたとき、わたしは…と感じた。…してほしい」。","Перескажи своими словами, что было услышано от другого человека, и уточни, верно ли это понято.":"相手から聞いたことを自分の言葉で言い直し、正しく受け取れたか確かめましょう。","Попробуй короткий ответ без длинного оправдания: «Сейчас я не могу. Давай обсудим другой вариант».":"長い言い訳なしの短い返事を試してみて：「今はできません。別の方法を話しましょう」。","Раздели лист: «за что отвечаю я» и «за что отвечает другой». Не бери на себя обе стороны.":"紙を2つに分けて：「自分が責任を持つこと」と「相手が責任を持つこと」。両方を背負わないで。","Пауза в разговоре":"会話の小休止","Если разговор накаляется, предложи вернуться к нему в конкретное время после паузы.":"会話が熱くなってきたら、休憩をはさんで時間を決めて話し直そうと提案しましょう。","Запиши: как я хочу поддерживать контакт и что мне при этом важно решать самостоятельно.":"書き出しましょう：どうつながっていたいか、そして何を自分で決めたいか。","Один вопрос":"ひとつの質問","Вместо догадки спроси: «Что именно ты имеешь в виду?» Дай другому возможность прояснить слова.":"推測する代わりに「具体的にはどういう意味？」と聞いて、相手に説明する機会をあげましょう。","Если хочется контакта, отправь простое сообщение без ожидания немедленного ответа.":"つながりたいときは、すぐの返事を期待せずにシンプルなメッセージを送りましょう。","После сложного разговора запиши конкретные задачи и договорённости отдельно от тона и эмоций.":"つらい会話のあとは、具体的な作業と約束を、口調や感情とは分けて書き出しましょう。","Уточнить приоритет":"優先順位を確かめる","Спроси, какое из двух дел важнее сегодня. Это превращает неопределённость в выбор.":"2つのうち今日はどちらが大事か聞いてみましょう。不確かさが選択に変わります。","Составь спокойный черновик: факт, уточняющий вопрос и срок, когда вернёшься с ответом.":"落ち着いた下書きを：事実、確認の質問、いつ返事をするか。","Раздели обратную связь на полезную часть, спорную часть и форму подачи. Возьми только то, что поможет задаче.":"フィードバックを、役立つ部分・異論のある部分・伝え方に分け、作業に役立つものだけ受け取りましょう。","Маленькая победа":"小さな勝利","Запиши одно завершённое дело за день. Даже если другие ещё ждут.":"今日終えたことをひとつ書きましょう。ほかがまだ残っていても。","Переход домой":"家モードへの切り替え","Закрой рабочий день короткой заметкой о первом шаге на завтра. Переключись на другую деятельность.":"明日の最初の一歩を短くメモして仕事を締めくくり、別のことに切り替えましょう。","Найти союзника":"味方を見つける","Подумай, кто может помочь уточнить задачу, дать контекст или поддержать после трудного разговора.":"作業をはっきりさせたり、背景を教えたり、つらい会話のあとに支えてくれたりする人は誰か考えましょう。","Вернуться к опоре, отделить событие от мыслей и выбрать свой следующий шаг.":"支えに戻り、出来事と考えを分けて、次の一歩を選ぶ。","Проверь сон, еду, воду и паузы. Выбери самое доступное сейчас.":"睡眠・食事・水分・休憩を確かめて、今いちばん手が届くものを選びましょう。","Сократи задачу до действия на две минуты. Можно остановиться после него.":"作業を2分でできる行動まで小さくしましょう。そのあとやめてもかまいません。","Не объяснять усталость":"疲れを説明しなくていい","Скажи себе: «Сил мало, и я могу выбрать посильный темп». Определи один обязательный пункт.":"「力は少ないけれど、無理のないペースを選べる」と自分に言いましょう。必須のことをひとつだけ決めます。","Пауза без экрана":"画面から離れるひと休み","На несколько минут убери экран и посмотри вдаль или закрой глаза, если комфортно.":"数分間、画面を置いて遠くを見るか、楽なら目を閉じましょう。","Сформулируй конкретную небольшую просьбу человеку, который может помочь.":"助けてくれそうな人に、具体的で小さなお願いを言葉にしましょう。","Список «потом»":"「あとで」リスト","Запиши необязательные дела в список на другой день, чтобы не держать их в голове.":"急がないことは別の日のリストに書いて、頭の中に抱えないようにしましょう。","Если есть силы и безопасно, пройди несколько минут в удобном темпе. Отдых тоже остаётся вариантом.":"力があって安全なら、楽なペースで数分歩いてみましょう。休むことも選べます。","Один приятный момент":"心地よいひととき","Выбери простую вещь, которая не требует подготовки: музыка, вода, окно или тёплый душ.":"準備のいらない簡単なことを選びましょう：音楽、水、窓辺、あたたかいシャワー。","Мысль или факт":"考えか事実か","Запиши тревожную мысль и рядом — факты за и против. Оставь место для неизвестного.":"不安な考えを書き、その横に賛成・反対の事実を書きましょう。わからないことの余地も残して。","Название мысли":"考えに名前をつける","Когда мысль повторяется, произнеси: «У меня появилась мысль, что…». Это создаёт небольшую дистанцию.":"考えがくり返すときは「〜という考えが浮かんでいる」と言ってみましょう。少し距離ができます。","Круг влияния":"影響の輪","Раздели ситуацию на то, что можешь изменить, на что можешь повлиять и что сейчас вне контроля.":"状況を「変えられること」「影響できること」「今はどうにもならないこと」に分けましょう。","Один следующий шаг":"次の一歩をひとつ","Вместо полного плана выбери действие, которое можно сделать сегодня.":"完ぺきな計画の代わりに、今日できる行動をひとつ選びましょう。","Вернуться к ощущениям":"感覚に戻る","Назови три звука, две видимые детали и одно ощущение от поверхности под рукой.":"3つの音、見える細部を2つ、手の下の面の感触をひとつ言葉にしましょう。","Время для мысли":"考えるための時間","Если мысль возвращается, запиши её и назначь короткое время позже, когда сможешь к ней вернуться.":"考えが戻ってくるなら書き留めて、あとで向き合う短い時間を決めましょう。","Два объяснения":"2つの説明","Найди ещё одно возможное объяснение событию, кроме самого пугающего. Не обязательно верить в него сразу.":"いちばん怖い説明のほかに、もうひとつ考えられる説明を探しましょう。すぐに信じなくてかまいません。","Спросить, а не угадать":"推測せずに聞く","Если мысль касается намерений другого, сформулируй вопрос, который поможет прояснить ситуацию.":"人の意図についての考えなら、状況をはっきりさせる質問を考えてみましょう。","Что уже помогает":"すでに助けになっていること","Заметь, что сейчас поддерживает тебя: человек, место, движение или привычка. Сохрани это в памяти.":"今あなたを支えているものに気づきましょう：人、場所、からだを動かすこと、習慣。覚えておいて。","Поблагодарить себя":"自分にありがとう","Назови один свой шаг сегодня без оценки его масштаба.":"今日踏み出した一歩をひとつ、大きさを評価せずに挙げましょう。","Фото момента":"その瞬間の写真","Опиши словами спокойный момент: цвет, звук, температуру и чувство в теле.":"穏やかな瞬間を言葉で描いてみましょう：色、音、温度、からだの感じ。","Забота на завтра":"明日へのケア","Выбери одну маленькую вещь, которую хочется повторить завтра.":"明日もくり返したい小さなことをひとつ選びましょう。","Делиться хорошим":"いいことを分かち合う","Если хочется, расскажи кому-то о приятном моменте, не превращая это в отчёт.":"よかったら、心地よかった瞬間を誰かに話してみましょう。報告にしなくていいんです。","Просто побыть":"ただ過ごす","Разреши себе несколько минут ничего не улучшать. Замечай, что уже есть.":"数分間、何もよくしようとしない時間を自分にあげましょう。すでにあるものに気づいて。","Мягкий план":"やさしい計画","Пока спокойно, запиши, что обычно помогает в более сложные дни.":"落ち着いているうちに、つらい日にいつも助けになることを書いておきましょう。","Свободное время":"自由な時間","Оставь в дне небольшой отрезок без обязательного результата.":"一日のなかに、成果を求めない短い時間を残しましょう。","2 минуты":"2分","Дыши комфортно, без задержки и усилия. На вдохе круг расширяется, на выдохе сужается. Если кружится голова, остановись и дыши обычно.":"息を止めたり力んだりせず、楽に呼吸しましょう。吸うと円が広がり、吐くと小さくなります。めまいがしたら止めて、ふつうに呼吸してください。","Начать дыхание":"呼吸をはじめる","Закончить":"終わる","Дыши в своём ритме":"自分のリズムで呼吸して","1 минута":"1分","Назови 5 вещей, которые видишь; 4, которые ощущаешь телом; 3 звука. Не спеши. Сейчас ты здесь.":"見えるものを5つ、からだで感じるものを4つ、音を3つ挙げましょう。急がなくて大丈夫。今、あなたはここにいます。","Представь между собой и резкими словами прозрачное стекло. Слова остаются по ту сторону. Спроси себя: что из сказанного относится к задаче, а что говорит о состоянии другого человека?":"自分ときつい言葉のあいだに透明なガラスがあると想像しましょう。言葉は向こう側にとどまります。言われたことのうち、作業に関することと、相手の状態を表していることはどれでしょう？","3 минуты":"3分","Запиши три короткие строки: 1) Что произошло? 2) Что я сейчас чувствую? 3) Какой один небольшой шаг мне доступен? Не нужно искать идеальное решение.":"短く3行書きましょう：1）何が起きた？ 2）今どう感じている？ 3）できる小さな一歩は？ 完ぺきな答えはいりません。","Если бы близкий человек оказался на твоём месте, какие слова поддержки нашлись бы для него? Попробуй обратиться с этой же фразой к себе.":"身近な人があなたの立場にいたら、どんな励ましの言葉をかけますか？ 同じ言葉を自分にもかけてみましょう。","Если есть возможность, встань, сделай несколько спокойных шагов и выпей воды. Посмотри в окно или выйди на воздух. Потом проверь, изменилось ли что-то хотя бы на один процент.":"できれば立ち上がって、ゆっくり数歩歩き、水を飲みましょう。窓の外を見るか、外の空気を吸いに出て。それから、1％でも何か変わったか確かめます。","1 мин":"1分","2 мин":"2分","3 мин":"3分","5 мин":"5分","10 мин":"10分","✦ РЯДОМ · ПРАКТИКА":"✦ RYADOM · プラクティス","ПЕРЕД НАЧАЛОМ":"はじめる前に","Что осталось после разговора?":"会話のあと、何が残っていますか？","Нам не нужно сейчас разбирать всё сразу. Отметь, с кем был разговор и насколько сильно он задел тебя в данный момент.":"今すべてを整理しなくて大丈夫。誰との会話だったか、今どれくらいこたえているかを選びましょう。","На работе":"職場で","С близким":"身近な人と","В другой ситуации":"ほかの場面で","Насколько сильно задело сейчас?":"今、どれくらいこたえていますか？","Немного":"少し","Очень сильно":"とても","Если сейчас небезопасно или ситуация продолжается, сначала позаботься о своей безопасности и обратись к человеку рядом. Практику можно закрыть в любой момент.":"今安全でない、または状況が続いているなら、まず自分の安全を守り、近くの人に頼ってください。プラクティスはいつでも閉じられます。","Начать →":"はじめる →","01 · ВЕРНУТЬСЯ В МОМЕНТ":"01 · 今に戻る","Сейчас ты здесь":"今、あなたはここにいる","Не нужно менять дыхание. Найди глазами одну вещь вокруг, услышь один звук и почувствуй опору под ногами или телом. Нажми на то, что удалось заметить.":"呼吸を変えなくて大丈夫。まわりのものをひとつ目で見つけ、音をひとつ聞き、足やからだの下の支えを感じましょう。気づけたものをタップしてください。","здесь":"ここ","и сейчас":"そして今","○ Вижу предмет":"○ ものが見える","○ Слышу звук":"○ 音が聞こえる","○ Чувствую опору":"○ 支えを感じる","Можно просто прочитать и двигаться дальше. Если внимание к телу неприятно, пропусти этот шаг.":"読むだけで先に進んでもかまいません。からだに注意を向けるのがつらければ、このステップは飛ばしましょう。","Назад":"戻る","Продолжить →":"続ける →","✓ Вижу предмет":"✓ ものが見える","✓ Слышу звук":"✓ 音が聞こえる","✓ Чувствую опору":"✓ 支えを感じる","02 · ОТДЕЛИТЬ СОБЫТИЕ ОТ МЫСЛИ":"02 · 出来事と考えを分ける","Две разные вещи":"2つの別のもの","Попробуй разделить то, что произошло, и то, что подумалось после. Это не проверка правильности твоих чувств. Поля можно оставить пустыми.":"起きたことと、そのあと浮かんだ考えを分けてみましょう。気持ちが正しいかのテストではありません。空欄のままでもかまいません。","Что было сказано или сделано?":"何を言われた、何をされた？","Какая мысль у меня об этом появилась?":"それについてどんな考えが浮かんだ？","Чувства реальны. Мысль о себе — не всегда факт. Необязательно находить объяснение прямо сейчас.":"気持ちは本物です。自分についての考えが、いつも事実とは限りません。今すぐ説明を見つけなくていいんです。","03 · ОДИН СЛЕДУЮЩИЙ ШАГ":"03 · 次の一歩","Что сейчас подойдёт?":"今、何が合いそう？","Выбери действие, которое зависит от тебя. Оно может быть маленьким и не обязано решать весь конфликт.":"自分しだいでできる行動を選びましょう。小さくていいし、対立のすべてを解決しなくていいんです。","Дать себе паузу":"自分に間をあげる","Можно ничего не отправлять прямо сейчас. Назначь момент, когда снова посмотришь на ситуацию.":"今は何も送らなくていいんです。もう一度状況を見直す時間を決めましょう。","Уточнить задачу":"作業を確かめる","Этот вариант подходит, если за неприятным тоном была конкретная рабочая задача.":"いやな口調の裏に具体的な仕事の用件があったなら、これが合います。","Обозначить границу":"線を引く","Подстрой слова под себя. Ты выбираешь время и безопасный способ разговора.":"言葉は自分に合うように変えて。時間と安全な話し方はあなたが選べます。","Попросить поддержки":"支えを頼む","Поддержка может быть короткой: сообщение, звонок или совместная прогулка.":"支えは短くていいんです：メッセージ、電話、一緒に散歩。","Как сейчас, по той же шкале?":"同じ目盛りで、今はどうですか？","Не хочу оценивать":"評価したくない","Завершить и сохранить →":"終えて保存 →","ВОЗМОЖНАЯ ФРАЗА":"言い方の例","«Я вернусь к разговору позже. Сейчас мне нужно немного времени».":"「この話はあとでまたしたいです。今は少し時間がほしいです」","Готово":"完了","ТВОЙ МАЛЕНЬКИЙ ШАГ":"あなたの小さな一歩","Можно остановиться здесь":"ここで終えてもいい","Состояние замечено, действие выбрано. Не нужно заставлять себя чувствовать лучше.":"状態に気づき、行動を選びました。無理に気分をよくしなくていいんです。","ЧТО ВЫБРАНО":"選んだこと","Состояние пока не изменилось. Ты всё равно можешь остановиться или выбрать поддержку.":"状態はまだ変わっていません。それでも、ここで終えるか支えを選べます。","В дневник сохранены только тема, выбранный шаг и твоя оценка результата. Написанные тобой фразы не сохранялись.":"日記に保存したのは、テーマ・選んだ一歩・あなたの評価だけです。書いた文は保存していません。","Вернуться в приложение":"アプリに戻る","Добавить место":"場所を追加","Название *":"名前 *","Например, любимая кофейня":"例：お気に入りのカフェ","Район или адрес":"地区や住所","Необязательно":"任意","Примерное время":"おおよその時間","Что это за место?":"どんな場所？","Кафе":"カフェ","Парк":"公園","Прогулка":"散歩","Культура":"文化","Другое":"その他","Как тебе там было?":"そこでの気分は？","Спокойно":"穏やか","Радостно":"うれしい","Уютно":"居心地がいい","Грустно":"悲しい","По-разному":"いろいろ","Что запомнилось?":"心に残ったことは？","Отмена":"キャンセル","Сохранить место":"場所を保存","Удалить разговоры, отметки, места и любимые места из дневника на этом устройстве? Игровой прогресс останется.":"この端末の日記から、会話・記録・場所・お気に入りを削除しますか？ゲームの進行は残ります。","{x}: {0}":"{x}：{0}","Сообщений в разговоре":"会話のメッセージ","Практик открыто":"開いたプラクティス","Тренажёров начато":"始めたトレーニング","Тренажёров пройдено":"終えたトレーニング","Открытий «Практик»":"「プラクティス」を開いた回数","Открытий «Игр»":"「ゲーム」を開いた回数","Открытий «Мест»":"「場所」を開いた回数","Открытий дневника":"日記を開いた回数","{x}: {y} {0} из {1}":"{x}：{y} {0}/{1}","тревога":"不安","грусть":"悲しさ","беспокойство":"落ち着かなさ","спокойствие":"落ち着き","Да, удалить":"はい、削除","Неспешная прогулка, книга или чашка чая. Выбирай только то, на что есть силы.":"ゆっくり散歩、本、または一杯のお茶。力が残っているものだけを選んでね。","Место, где можно сменить обстановку. Тишину и отсутствие людей лучше проверить самому.":"気分転換できる場所。静かさや人の多さは自分で確かめてね。","Прогулка, вид на город или уютное место для встречи.":"散歩、街の眺め、または会うのに居心地のいい場所。","Места, где можно гулять, смотреть кино или быть среди людей.":"散歩したり、映画を観たり、人の中にいられる場所。","Пространства для неторопливого времени.":"ゆったり過ごすための場所。","Музей, галерея или книжное место могут дать новую мысль.":"美術館やギャラリー、本のある場所が新しい考えをくれるかも。","Поблизости и без большого плана: кофе или короткая прогулка.":"近くで、大きな計画なしに：コーヒーか短い散歩。","Места для встречи. Загруженность и атмосферу уточни перед поездкой.":"会うための場所。混雑や雰囲気は行く前に確かめてね。","Будут удалены дневник, разговоры, «Обо мне», места и прогресс игр на этом устройстве. Вернуть их будет нельзя, если нет копии.":"この端末の日記、会話、「わたしについて」、場所、ゲームの進み具合が削除されます。コピーがなければ元に戻せません。","Да, удалить всё":"はい、すべて削除","Удалить все записи профиля? Вернуть их будет нельзя.":"プロフィールの記録をすべて削除しますか？元に戻せません。","Да, стереть":"はい、消去","После нескольких отметок здесь появится короткое наблюдение о твоём состоянии.":"何度か記録すると、ここにあなたの状態についての短い気づきが表示されます。","Здесь появятся твои отметки после первого разговора.":"最初の会話のあと、ここに記録が表示されます。","Разговор с «Рядом»":"Ryadom との会話","Например: трудный разговор, прогулка или приятный момент":"例：難しい会話、散歩、うれしい瞬間","Интерактивный прототип приложения ежедневной эмоциональной поддержки.":"毎日の心のサポートアプリのインタラクティブなプロトタイプ。","Твои мысли остаются только на этом экране и не сохраняются":"あなたの考えはこの画面にだけ残り、保存されません","Заметка":"メモ","Как ты сейчас после этого шага?":"このステップのあと、今はどう？","Чуть легче":"少し楽になった","Пока так же":"今のところ変わらない","Стало хуже":"悪くなった","День":"日","Отмечено состояний: {0}. График показывает только твои ответы, без оценок и диагнозов.":"記録した状態：{0}。グラフはあなたの回答だけを示し、評価や診断はしません。","Одна короткая отметка в день — уже начало.":"1日1回の短い記録が、もう始まりです。","Удалить все отметки из этого браузера?":"このブラウザの記録をすべて削除しますか？","В {0} из {1} отмеченных дней тревога была сильной. Можно посмотреть, что происходило в эти дни, и обратиться за поддержкой, если это мешает жить.":"記録した {1} 日のうち {0} 日は不安が強めでした。その日に何があったか振り返り、生活に支障があるならサポートを求めることもできます。","За выбранный период сильная тревога отмечалась в {0} из {1} дней. Посмотри, какие занятия и разговоры помогали тебе чувствовать себя спокойнее.":"選んだ期間では {1} 日中 {0} 日に強い不安が記録されました。どんな活動や会話で落ち着けたか見てみよう。","На этот день нет записи. Пустая клетка ничего не говорит о том, каким был день.":"この日の記録はありません。空欄はその日がどうだったかを何も示しません。","чуть легче":"少し楽に","без изменений":"変化なし","стало хуже":"悪化","без оценки":"評価なし","Удалить разговоры, отметки и заметки дневника из этого браузера? Игровой прогресс останется.":"このブラウザの会話、記録、日記メモを削除しますか？ゲームの進み具合は残ります。","Скоро":"近日公開","Ничего не найдено. Попробуй другое слово или состояние.":"見つかりませんでした。別の言葉や状態で試してね。","Поддержка":"サポート","Мне очень жаль, что сейчас так тяжело. Если есть риск причинить себе вред прямо сейчас, позови человека рядом и обратись за срочной помощью по местному экстренному номеру. Ты можешь сказать: «Мне сейчас небезопасно оставаться одной или одному. Побудь со мной и помоги получить помощь».":"今こんなにつらいなんて、本当に心が痛みます。今すぐ自分を傷つけてしまいそうなら、近くの人を呼び、地域の緊急番号で急いで助けを求めてください。こう言えます：「今ひとりでいるのは安全じゃない。そばにいて、助けを得るのを手伝って」。","Показать фразу для близкого":"身近な人に送る言葉を表示","Можно отправить: «Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь со мной. Помоги обратиться за помощью».":"こう送れます：「今とてもつらい。電話するか、そばにいてほしい。助けを求めるのを手伝って」。","Хорошо, что об этом сказано вслух. Если состояние изменится, обратись к человеку рядом или за срочной помощью.":"口に出せてよかった。状態が変わったら、近くの人か緊急の助けに頼ってね。","Начнём новый разговор. Как ты сейчас?":"新しい会話を始めよう。今どんな感じ？","Рада это слышать. Что сегодня помогло тебе чувствовать себя так?":"それを聞けてうれしい。今日そう感じられたのは何のおかげ？","Спасибо, что об этом сказано. Что произошло или когда это ощущение появилось? Можно ответить своими словами.":"話してくれてありがとう。何があった？ その気持ちはいつから？ 自分の言葉で答えていいよ。","Близкие":"身近な人","Не знаю, почему":"なぜかわからない","Понимаю. Насколько сильно это сейчас ощущается — от 1 до 4? Если сложно оценить, можно пропустить.":"わかるよ。今どのくらい強い？1〜4で。難しければスキップしてもいい。","1 · немного":"1 · 少し","2 · заметно":"2 · はっきり","3 · сильно":"3 · 強く","4 · очень сильно":"4 · とても強く","Пропустить":"スキップ","Что хочется сделать с этим ощущением?":"この気持ちをどうしたい？","Что сейчас было бы нужнее: немного успокоиться, разобраться в ситуации, просто выговориться или отдохнуть?":"今いちばん必要なのは：少し落ち着く、状況を整理する、ただ話す、休む、のどれ？","Успокоиться":"落ち着く","Разобраться":"整理する","Выговориться":"話してすっきりする","Отдохнуть":"休む","Я слушаю. Расскажи, что было самым неприятным или важным в этом моменте.":"聞いているよ。その瞬間でいちばん嫌だったこと、大事だったことを話して。","Похоже, это действительно задело. Что хотелось бы получить сейчас? Можно выбрать маленький шаг, а можно продолжить разговор.":"本当に傷ついたみたいだね。今どうしたい？ 小さな一歩を選んでも、話を続けてもいいよ。","Рассказать ещё":"もっと話す","Закончить пока":"今はここまで","Я рядом. Что ещё важно сказать?":"ここにいるよ。ほかに言っておきたい大事なことは？","Спасибо, что поделилась или поделился. Можно вернуться, когда захочешь.":"話してくれてありがとう。いつでも戻ってきてね。","Новый разговор":"新しい会話","Я слушаю. Что хочется рассказать?":"聞いているよ。何を話したい？","Спасибо за разговор. Вернись, когда захочешь.":"話してくれてありがとう。いつでも戻ってきてね。","Слышу тебя. Что из этого сейчас важнее всего? Можешь рассказать ещё или выбрать шаг.":"ちゃんと聞いているよ。この中で今いちばん大事なのは？ もっと話しても、一歩を選んでもいい。","Рада, что стало хоть немного легче. Что именно помогло?":"少しでも楽になってよかった。何が助けになった？","Жаль, что стало хуже. Остановимся с этой практикой. Сейчас лучше выбрать более мягкую поддержку или обратиться к близкому человеку.":"悪くなってしまって残念。この練習はやめよう。今はもっとやさしいサポートを選ぶか、身近な人に頼るのがいいよ。","Хорошо, что это получилось заметить. Можно попробовать другой шаг или просто остановиться.":"気づけたのはいいこと。別のステップを試しても、ここでやめてもいいよ。","Расскажу ещё":"もう少し話す","Я слушаю. Что сейчас на первом плане?":"聞いているよ。今いちばん気になっているのは？","Спасибо за разговор. Береги свой темп.":"話してくれてありがとう。自分のペースを大切にね。","Если захочешь, начнём новый разговор.":"よければ、新しい会話を始めよう。","Тогда начнём с очень маленькой паузы.":"じゃあ、ほんの小さな休憩から始めよう。","Давай отделим то, что произошло, от догадок.":"起きたことと推測を分けてみよう。","Можно попробовать один из этих шагов. Выбирай только то, что подходит.":"このステップのどれかを試せるよ。合うものだけ選んでね。","Хочу рассказать ещё":"もっと話したい","Пока достаточно":"今はこれで十分","Как ты после этого шага?":"このステップのあと、どう？","Голосовой ввод не поддерживается этим браузером":"このブラウザは音声入力に対応していません","Голосовой ввод недоступен в этом браузере. Можно писать текстом.":"このブラウザでは音声入力を使えません。文字で書いてね。","Распознавание голоса выполняет устройство и может передавать запись его сервису. Продолжить?":"音声認識は端末が行い、録音が端末のサービスに送られることがあります。続けますか？","Да, включить":"はい、オンにする","Остановить запись":"録音を停止","Слушаю. Фраза появится в поле ввода — проверь её перед отправкой.":"聞いています。言葉は入力欄に表示されます。送る前に確認してね。","Проверь текст и нажми отправить, когда текст устроит.":"テキストを確認して、よければ送信してね。","Нет доступа к микрофону. Можно продолжить текстом.":"マイクにアクセスできません。文字で続けられます。","Не удалось распознать речь. Попробуй ещё раз или напиши текстом.":"音声を認識できませんでした。もう一度試すか、文字で書いてね。","Не удалось включить микрофон.":"マイクをオンにできませんでした。","4–6 минут":"4〜6分","Небольшая самостоятельная практика после неприятного разговора.":"嫌な会話のあとにひとりでできる短い練習。","После трудного разговора · 4–6 минут":"難しい会話のあとで · 4〜6分","«Помоги понять: какой результат ожидается и к какому сроку?»":"「教えてください。どんな結果を、いつまでに求めていますか？」","«Мне важно обсудить вопрос, когда мы можем говорить спокойно».":"「落ち着いて話せるときに、この件を話し合いたいです」","«У меня был трудный разговор. Можешь немного побыть со мной на связи?»":"「難しい会話があったんだ。少しのあいだ、つながっていてくれる？」","Шаг {0} из 4":"ステップ {0}/4","Пауза":"休止","Результат не оценён. Это тоже нормально.":"結果は評価されていません。それでも大丈夫。","Отмечено небольшое облегчение.":"少し楽になったと記録しました。","Стало тяжелее. Эту практику можно оставить и обратиться к человеку, которому доверяешь.":"つらくなったね。この練習はやめて、信頼できる人に頼ってもいいよ。","Вижу предмет":"物が見える","Слышу звук":"音が聞こえる","Чувствую опору":"支えを感じる","Например: «Руководитель повысил голос и попросил переделать отчёт»":"例：「上司が声を荒げて、報告書をやり直すよう言った」","Например: «Наверное, я ни на что не способна или не способен»":"例：「たぶん自分は何もできない」","Практика пройдена в твоём темпе. Хочешь рассказать ещё или закончить?":"自分のペースで練習できたね。もっと話す？ それとも終える？","Отмечено, что стало немного легче. Хочешь остановиться или рассказать, какой шаг оказался выбран?":"少し楽になったと記録しました。ここでやめる？ それともどのステップを選んだか話す？","Похоже, сейчас стало тяжелее. Остановимся. Можно обратиться к человеку рядом или выбрать другую поддержку.":"つらくなったみたい。いったん止めよう。近くの人に頼るか、別のサポートを選んでね。","Спасибо за оценку результата. Хочешь рассказать ещё или закончить?":"評価してくれてありがとう。もっと話す？ それとも終える？","тревожно":"不安","тяжело":"しんどい","злюсь":"怒っている","нормально":"ふつう","хорошо":"いい","✓ Сделано":"✓ 完了","Скопировано":"コピーしました","Не удалось":"できませんでした","Запись о тебе сейчас выключена. Включить её можно в разделе «Обо мне».":"あなたについての記録は今オフです。「わたしについて」でオンにできます。","Такая запись уже есть или список полон.":"同じ記録がすでにあるか、リストがいっぱいです。","Избранные места":"お気に入りの場所","Найденные места":"見つかった場所","Выбранный город":"選んだ街","Счётчики на этом устройстве":"この端末のカウンター","Цепочки практик":"練習のつながり","Согласие на голос":"音声の同意","Настройка озвучки":"読み上げの設定","Прогресс игр":"ゲームの進み具合","Прогресс историй":"ストーリーの進み具合","Прогресс квестов":"クエストの進み具合","Не удалось прочитать: это не файл данных «Рядом».":"読み込めませんでした：Ryadom のデータファイルではありません。","Это не файл данных «Рядом».":"Ryadom のデータファイルではありません。","В файле нет данных для восстановления.":"ファイルに復元できるデータがありません。","Пока ничего не сохранено":"まだ何も保存されていません","Данные для переноса":"引き継ぎ用データ","Выбери, куда сохранить: «Файлы», облако, почта или мессенджер себе.":"保存先を選んで：「ファイル」、クラウド、メール、または自分宛てのメッセンジャー。","Не получилось открыть «Поделиться». Воспользуйся кнопкой «Скопировать текст».":"「共有」を開けませんでした。「テキストをコピー」ボタンを使ってね。","Файл сохраняется. Если ничего не произошло — воспользуйся кнопкой «Скопировать текст».":"ファイルを保存しています。何も起きなければ「テキストをコピー」を使ってね。","Не получилось сохранить файл. Воспользуйся кнопкой «Скопировать текст».":"ファイルを保存できませんでした。「テキストをコピー」を使ってね。","Скопировано. Вставь в заметки или сообщение себе.":"コピーしました。メモや自分宛てのメッセージに貼り付けてね。","Скопировать автоматически не вышло. Текст выделен — скопируй его вручную.":"自動でコピーできませんでした。テキストを選択したので手動でコピーしてね。","Файл слишком большой.":"ファイルが大きすぎます。","Вставь сюда скопированный текст и нажми кнопку ещё раз":"コピーしたテキストをここに貼り付けて、もう一度ボタンを押してね","Всё удалено. Обновляю приложение…":"すべて削除しました。アプリを再読み込みしています…","Где хранятся":"保存場所","Что передаётся наружу":"外部に送られるもの","Что приложение не делает":"アプリがしないこと","Важно":"大切なこと","Новых мест для добавления нет. Отметь любимые в разделе «Места» или посещения в дневнике.":"追加できる新しい場所はありません。「場所」でお気に入りを、日記で訪れた場所を記録してね。","Сейчас записи не используются: ни в разговоре, ни в подсказках, ни на сервере.":"今は記録を使っていません：会話でも、ヒントでも、サーバーでも。","Романтично":"ロマンチック","Весело":"楽しい","Хочется нового":"新しいことがしたい","Устало":"疲れた","Хочется общения":"人と話したい","Расстояние неизвестно":"距離不明","Сад":"庭園","Библиотека":"図書館","Музей":"博物館","Смотровая площадка":"展望台","Ресторан":"レストラン","Галерея":"ギャラリー","Кинотеатр":"映画館","Театр":"劇場","Достопримечательность":"名所","Арт-пространство":"アートスペース","Книжный магазин":"書店","Бар":"バー","Уже есть в твоём дневнике":"日記にもうあります","Отметок об этом месте в дневнике: {0}":"この場所の日記の記録：{0}","Любимое место · под выбранное настроение может подойти другое":"お気に入りの場所 · 選んだ気分には別の場所が合うかも","На карте ↗":"地図で見る ↗","Была/был здесь":"ここに行った","01 / ТВОИ МЕСТА":"01 / あなたの場所","Любимые сначала":"お気に入りを先に","02 / ПОБЛИЗОСТИ":"02 / 近く","Новые места рядом":"近くの新しい場所","Показано {0} мест рядом с «{1}».":"「{1}」の近くの場所を {0} 件表示しています。","Найдено {0} мест в радиусе около 2 км. Данные OpenStreetMap могут быть неполными.":"半径約2km以内に {0} 件見つかりました。OpenStreetMap のデータは不完全な場合があります。","Поблизости пока не нашлось мест под это настроение. Попробуй другой район или настроение.":"近くにこの気分に合う場所はまだ見つかりません。別のエリアや気分で試してね。","Поиск новых мест сейчас недоступен. Любимые места из дневника остаются здесь. Попробуй позже или укажи другой район.":"新しい場所の検索は今使えません。日記のお気に入りの場所はここに残ります。あとで試すか、別のエリアを指定してね。","Этот браузер не поддерживает определение местоположения. Введи город вручную.":"このブラウザは位置情報に対応していません。街の名前を入力してね。","Запрашиваем местоположение…":"位置情報を取得中…","текущей точки":"現在地","Не удалось получить местоположение. Введи город или район вручную.":"位置情報を取得できませんでした。街やエリアを入力してね。","Не удалось найти этот город или район. Попробуй уточнить название.":"この街やエリアが見つかりませんでした。名前を詳しくしてみてね。","Не удалось найти город сейчас. Попробуй ещё раз позже или используй геолокацию.":"今は街を見つけられませんでした。あとで試すか、位置情報を使ってね。","Убрать из любимых":"お気に入りから外す","Изменить место":"場所を変更","Или выбери любимое:":"またはお気に入りから選ぶ：","Ты":"あなた","МЕНЮ":"メニュー","Попробовать ещё раз":"もう一度試す","Дальше →":"次へ →","Скопировать":"コピー","Сначала напиши свою версию.":"まず自分の言葉で書いてね。","Скопировано.":"コピーしました。","Скопируй текст вручную.":"テキストを手動でコピーしてね。","Запомнить в «Обо мне»":"「わたしについて」に保存","Записано в «Обо мне».":"「わたしについて」に保存しました。","К играм":"ゲームへ","Озвучка ответов включена":"返事の読み上げがオンです","Озвучка включена.":"読み上げをオンにしました。","Данные «Рядом»":"Ryadom のデータ","Копия данных приложения «Рядом». Храни её в надёжном месте.":"Ryadom アプリのデータのコピーです。安全な場所に保管してね。","Сохранить копию":"コピーを保存","Как ты сегодня? Можно отметить состояние за минуту.":"今日はどう？ 1分で気持ちを記録できるよ。","Минутка для себя: как прошёл день?":"自分のための1分：今日はどんな日だった？","Если день был непростым — я рядом. Можно просто отметить настроение.":"大変な日だったなら、ここにいるよ。気分を記録するだけでもいい。","Напоминания недоступны на этом устройстве.":"この端末ではリマインダーを使えません。","Напоминание выключено.":"リマインダーをオフにしました。","Уведомления запрещены. Их можно разрешить в настройках телефона для приложения «Рядом».":"通知がブロックされています。スマホの設定で Ryadom アプリの通知を許可できます。","Напоминание":"リマインダー","Раз в день мягко напомню отметить состояние. Работает без интернета, ничего никуда не отправляется.":"1日1回、そっと状態の記録をお知らせします。オフラインで動き、何も送信しません。","Ежедневное напоминание":"毎日のリマインダー","Каждый день":"毎日","Время напоминания":"通知の時刻","Похоже, сейчас тревожно.":"今、不安なんだね。","Похоже, сейчас грустно.":"今、悲しいんだね。","Похоже, сейчас много злости.":"今、怒りが大きいんだね。","Похоже, сил сейчас совсем немного.":"今、エネルギーがほとんどないんだね。","Похоже, сейчас одиноко.":"今、さみしいんだね。","Похоже, это задело.":"傷ついたんだね。","Похоже, рядом с этим есть чувство вины или стыда.":"罪悪感や恥ずかしさもあるみたいだね。","Как хорошо это слышать!":"それを聞けてうれしい！","Слышу, что это связано с работой.":"仕事に関係していることなんだね。","Слышу, что это связано с семьёй.":"家族に関係していることなんだね。","Слышу, что это связано с отношениями.":"恋愛や関係に関係していることなんだね。","Слышу, что это связано с друзьями.":"友だちに関係していることなんだね。","Слышу, что это связано со здоровьем.":"健康に関係していることなんだね。","Слышу, что это связано с деньгами.":"お金に関係していることなんだね。","Слышу, что это связано с учёбой.":"勉強に関係していることなんだね。","Я слушаю. Что было дальше?":"聞いているよ。それからどうなった？","Это звучит непросто. Что сейчас ощущается сильнее всего?":"大変そうだね。今いちばん強く感じているのは？","Понимаю. Что для тебя здесь самое важное?":"わかるよ。ここであなたにとっていちばん大事なのは？","Спасибо, что рассказываешь. Как это на тебя повлияло?":"話してくれてありがとう。それはあなたにどう影響した？","Если посмотреть на это со стороны — что хотелось бы изменить в первую очередь?":"外から眺めてみたら、まず何を変えたい？","Что помогло бы тебе хоть немного прямо сейчас?":"今、少しでも助けになるのは何？","Злюсь":"怒っている","Одиноко":"さみしい","Всё хорошо":"大丈夫","Куда сегодня сходить?":"今日はどこへ行く？","Просто выговориться":"ただ話したい","Небольшой шаг, чтобы стало легче":"楽になるための小さな一歩","Потренировать трудный разговор":"難しい会話を練習する","Куда сходить или что поесть":"どこへ行く？ 何を食べる？","Привет. Я — «Рядом». Можно написать, как ты, своими словами или выбрать подсказку.":"こんにちは。Ryadom です。今の気持ちを自分の言葉で書くか、ヒントを選んでね。","На этом языке я понимаю простые фразы. Подсказки-кнопки помогут быть точнее.":"この言語では簡単な文を理解できます。ヒントのボタンを使うとより正確になります。","Как хорошо это слышать! Что сегодня порадовало?":"それを聞けてうれしい！ 今日は何がうれしかった？","Куда сходить отметить?":"お祝いにどこへ行く？","Записать в дневник":"日記に書く","Есть и сложная часть":"つらい部分もある","Что сейчас было бы полезнее?":"今、何がいちばん役に立ちそう？","Вот что можно попробовать. Любой шаг можно остановить.":"試せることはこれ。どのステップもやめていいよ。","Лучше просто поговорим":"ただ話そう","Подобрать небольшой шаг":"小さな一歩を選ぶ","Продолжу рассказывать":"話を続ける","Спасибо за разговор. Я здесь, когда захочется вернуться.":"話してくれてありがとう。戻りたくなったら、いつでもここにいるよ。","Начать новый разговор":"新しい会話を始める","Открыть дневник":"日記を開く","Похоже, сейчас очень много злости. Если есть риск навредить другому человеку — остановись и выйди из ситуации: на воздух, в другую комнату. Если опасность рядом — звони в экстренную службу.":"今、とても強い怒りがあるみたい。誰かを傷つけてしまいそうなら、手を止めてその場を離れて：外に出るか別の部屋へ。危険が近くにあるなら緊急通報を。","То, что ты описываешь, звучит небезопасно. Твоя безопасность важнее всего. Если опасность рядом прямо сейчас — постарайся уйти в безопасное место и позвони в экстренную службу.":"あなたが話していることは安全ではなさそう。あなたの安全がいちばん大切です。今すぐ危険が近くにあるなら、安全な場所へ移動して緊急通報してください。","Спасибо, что ты об этом говоришь. Твоя безопасность сейчас важнее всего. С этим не нужно справляться без поддержки: позвони на линию помощи или человеку, которому доверяешь.":"話してくれてありがとう。今はあなたの安全がいちばん大切です。ひとりで抱えなくていい：相談窓口か、信頼できる人に電話してください。","Показать текст для близкого":"身近な人に送る文を表示","Сейчас я в безопасности":"今は安全です","Если опасность прямо сейчас — экстренная служба: 112 (в большинстве стран).":"今すぐ危険があるなら——緊急通報：112（多くの国で利用可能）。","Линии помощи в других странах: findahelpline.com":"他の国の相談窓口：findahelpline.com","Пожалуйста. Я рядом.":"どういたしまして。ここにいるよ。","Нет, я не врач и не психолог: не ставлю диагнозов и не лечу. Я помогаю выговориться, назвать, что происходит, и сделать небольшой шаг. Если тяжёлое состояние держится долго или мешает жить, стоит обратиться к специалисту.":"いいえ、医師でも心理士でもありません。診断や治療はしません。話してすっきりすること、起きていることに名前をつけること、小さな一歩を踏み出すことを手伝います。つらい状態が長く続いたり生活に支障があるなら、専門家に相談してください。","Я «Рядом» — программа, а не человек. Я не врач и не заменяю специалиста.":"わたしは Ryadom。人ではなくプログラムです。医師ではなく、専門家の代わりにもなりません。","Хорошо, не будем. Ничего объяснять не нужно. Можно просто побыть рядом или выбрать другое.":"わかった、やめておこう。何も説明しなくていいよ。ただ一緒にいても、別のことを選んでもいい。","Я рядом. Начнём с самого простого: что сейчас ближе?":"ここにいるよ。いちばん簡単なことから始めよう：今いちばん近いのはどれ？","Привет. Что сейчас происходит? Можно написать своими словами или выбрать подсказку.":"こんにちは。今どんなことが起きてる？ 自分の言葉で書くか、ヒントを選んでね。","Это стоит запомнить. Хочешь отметить это — сходить куда-нибудь или записать в дневник?":"覚えておく価値があるね。どこかへ出かけるか、日記に書いて記念にする？","А что здесь сильнее всего?":"その中でいちばん強いのは？","Обида":"傷つき","Усталость":"疲れ","Хочу понять точнее. Что ближе всего к тому, что сейчас внутри? Можно выбрать подсказку.":"もっと正確に知りたい。今の心の中にいちばん近いのはどれ？ ヒントを選んでもいいよ。","Из того, что известно о тебе:":"あなたについて知っていることから：","В разделе «Места» можно выбрать настроение и посмотреть, что рядом.":"「場所」で気分を選ぶと、近くに何があるか見られます。","Открыть «Места»":"「場所」を開く","Расскажу, что на душе":"心の中のことを話す","Расскажи, что ещё происходит.":"ほかに何が起きているか話して。","Я слушаю. Можно писать как получается — кусками, без порядка.":"聞いているよ。思いつくままに、ばらばらでも順番どおりでなくてもいい。","Тренажёры трудных разговоров пока доступны только на русском языке. Можно открыть их или выбрать другое.":"難しい会話の練習は今のところロシア語のみです。開いても、別のものを選んでもいいよ。","Открыть тренажёры":"練習を開く","Я слушаю.":"聞いているよ。","Хорошо. Если станет хуже — линии помощи выше, и можно вернуться сюда в любой момент.":"わかった。悪くなったら上の相談窓口を見てね。いつでもここに戻ってこられるよ。","Можно отправить близкому:":"身近な人に送れる言葉：","Мне сейчас очень тяжело. Пожалуйста, побудь со мной или позвони мне сейчас. Помоги обратиться за помощью.":"今とてもつらい。そばにいるか、今すぐ電話してほしい。助けを求めるのを手伝って。","Хорошо, что стало хоть немного легче. Хочешь остановиться на этом или продолжить?":"少しでも楽になってよかった。ここでやめる？ それとも続ける？","Жаль, что стало тяжелее. Давай не продолжать эту практику. Можно связаться с близким человеком или выбрать другой, более мягкий шаг.":"つらくなってしまって残念。この練習は続けないでおこう。身近な人に連絡するか、もっとやさしい別の一歩を選んでね。","Иногда эффект приходит не сразу. Можно попробовать другой способ или просто поговорить.":"効果がすぐに出ないこともあるよ。別の方法を試しても、ただ話してもいい。","Другой способ":"別の方法","Подобрано {x}. Можно выбрать любое или ничего.":"選んだもの：{x}。どれを選んでも、何も選ばなくてもいい。","по последней отметке «{q}»":"最後の記録「{q}」から","по последней отметке «{q}» и позднему времени":"最後の記録「{q}」と遅い時間から","{x} · Открыть →":"{x} · 開く →","{0} из {1}":"{0}/{1}","Отметить шаг цепочки: {x}":"つながりのステップを記録：{x}","Открыть практику: {x}":"練習を開く：{x}","Открыть тренажёр: {x}":"会話練習を開く：{x}","Убрать «{q}»":"「{q}」を外す","Удалить: {x}":"削除：{x}","Идея на сегодня: {x}.":"今日のアイデア：{x}。","Идея на сегодня: {x}. Лучше без: {y}.":"今日のアイデア：{x}。避けたほうがいいもの：{y}。","поесть":"食べる","побыть":"過ごす","{0} Б":"{0} B","{0} КБ":"{0} KB","Данные восстановлены ({0}). Обновляю приложение…":"データを復元しました（{0}）。アプリを再読み込みしています…","Добавлено записей: {0}":"追加した記録：{0}","тебе обычно подходит — {x}. Выбирай места с учётом этого.":"ふだん合うもの — {x}。それを踏まえて場所を選んでね。","тебе обычно подходит — {x}. Лучше без: {y}. Выбирай места с учётом этого.":"ふだん合うもの — {x}。避けたほうがいいもの：{y}。それを踏まえて場所を選んでね。","{0} м":"{0} m","{0} км":"{0} km","Убрать из любимых: {x}":"お気に入りから外す：{x}","В любимые: {x}":"お気に入りに追加：{x}","«{q}» добавлено в дневник за сегодня.":"「{q}」を今日の日記に追加しました。","Ищем места рядом с «{q}»…":"「{q}」の近くの場所を探しています…","Ищем «{q}»…":"「{q}」を検索中…","Сохранён город «{q}». Выбирай настроение — подборка обновится.":"街「{q}」を保存しました。気分を選ぶとおすすめが更新されます。","Найдено практик: {0} из {1}":"見つかった練習：{0}/{1}","Показать ещё ({0})":"もっと見る（{0}）","В диалоге: {x}":"会話で：{x}","Удалить тексты разговоров за {x}? Отметки состояния останутся.":"{x} の会話テキストを削除しますか？ 状態の記録は残ります。","Практики: {x}":"練習：{x}","Шаг {0} из {1}":"ステップ {0}/{1}","Подсказка: {x}":"ヒント：{x}","Источник: {x}":"出典：{x}","Пройдено стилей: {0} из {1}":"クリアしたスタイル：{0}/{1}","День {0}":"{0}日目","{x} по дням":"{x}（日ごと）","Готово: каждый день в {0}:{1}. Пропускать можно — это просто приглашение.":"設定しました：毎日 {0}:{1}。スキップしても大丈夫、ただのお誘いです。","Чаще всего тебе помогала практика «{q}» ({0} раз). Это личная заметка, не медицинский вывод.":"いちばんよく助けになった練習は「{q}」（{0}回）。個人的なメモで、医学的な結論ではありません。","Удалить «{q}» из этого дня?":"この日から「{q}」を削除しますか？","{0} место":"{0} か所","{0} места":"{0} か所","{0} мест":"{0} か所","Играть: {x}":"遊ぶ：{x}","{0} мин":"{0}分","{0} минуты":"{0}分","{0} минут":"{0}分","{0} минута":"{0}分","{0}–{1} минут":"{0}〜{1}分","рядом":"ryadom","Я":"私","на каждый день":"毎日に","← К играм":"← ゲームへ",". Оценки и популярность в соцсетях появятся только после подключения проверенного источника данных.":"。評価やSNSでの人気は、確認済みのデータソースを接続した後にのみ表示されます。","есть разговор":"会話あり","есть отметка состояния":"状態の記録あり","есть посещённые места":"訪れた場所あり","Квесты и сюжетные игры пока доступны только на русском языке. Перевод появится в следующих версиях.":"クエストとストーリーゲームは今のところロシア語のみです。翻訳は今後のバージョンで追加されます。","Не знаю, как сказать":"どう言えばいいかわからない","Если сейчас очень тяжело":"いま、とてもつらいなら","С этим не нужно справляться в одиночку. Выбери то, что получится сейчас.":"ひとりで抱えなくていい。今できることを選んでね。","Позвонить":"電話する","Написать близкому":"身近な人に送る","Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь рядом. Помоги мне получить помощь.":"今とてもつらい。電話するか、そばにいてほしい。助けを得るのを手伝って。","Пережить ближайшие минуты":"この数分をやり過ごす","Медленный выдох длиннее вдоха. Назови пять вещей, которые видишь вокруг. Если рядом есть что-то опасное — отложи это подальше или выйди в другое место.":"ゆっくり、吸うより長く息を吐いて。まわりに見えるものを5つ言ってみて。近くに危ないものがあれば、遠くに置くか別の場所へ移って。","Дыхание вместе со мной":"一緒に呼吸しよう","Мой план безопасности":"わたしの安全プラン","Заполни, когда немного спокойнее. План останется только на этом устройстве и откроется здесь в трудную минуту.":"少し落ち着いているときに書いておいて。プランはこの端末にだけ残り、つらいときにここで開けます。","Как я понимаю, что мне становится хуже":"調子が悪くなってきたと気づくサイン","Что помогает мне хоть немного":"少しでも助けになること","Кому могу написать или позвонить":"連絡したり電話したりできる人","Как сделать обстановку вокруг безопаснее":"まわりをより安全にする方法","«Рядом» — не экстренная служба и может не распознать, что тебе плохо. Если есть риск для жизни, звони 112 или обратись к человеку рядом.":"Ryadom は緊急サービスではなく、あなたがつらいことに気づけない場合があります。命の危険があるときは 112 に電話するか、近くの人に頼ってください。","Мне очень плохо":"とてもつらい","Мне сейчас очень плохо — открыть помощь":"いまとてもつらい — 助けを開く","Открыть экран помощи":"助けの画面を開く","Прежде чем продолжить, хочу спросить прямо, потому что это важно: ты сейчас думаешь о том, чтобы причинить себе вред или не жить?":"続ける前に、大切なことなのではっきり聞かせてね。いま、自分を傷つけることや、生きていたくないと考えている？","Да":"はい","Не знаю":"わからない","Нет, это другое":"いいえ、別のこと","Спасибо за ответ. Продолжим.":"答えてくれてありがとう。続けよう。"},"lex":{"emo":{"fear":["不安","心配","怖い","こわい","緊張","パニック","ストレス"],"sad":["悲しい","かなしい","泣","落ち込","つらい","辛い","憂うつ","さびしい気持ち"],"anger":["怒","腹が立","むかつ","イライラ","いらいら","ムカ","嫌い"],"tired":["疲れ","つかれ","しんどい","だるい","眠い","元気がない","くたくた"],"lonely":["寂しい","さみしい","孤独","ひとり","一人","誰もいない"],"hurt":["傷つ","悔しい","裏切","バカにされ","侮辱"],"shame":["恥ずかし","罪悪感","申し訳","自分のせい"],"good":["元気","嬉しい","うれしい","楽しい","いい感じ","最高","落ち着"]},"theme":{"work":["仕事","会社","上司","職場","同僚","バイト"],"family":["家族","母","父","親","兄","姉","弟","妹","子ども","子供"],"love":["彼氏","彼女","夫","妻","恋人","恋愛","別れ","パートナー"],"friends":["友達","友だち","友人"],"health":["健康","病気","痛","医者","病院","体調"],"money":["お金","借金","給料","家賃","ローン"],"study":["学校","試験","テスト","勉強","大学","授業","先生","宿題"]},"intent":{"bye":["さようなら","またね","おやすみ","じゃあね"],"thanks":["ありがとう","感謝"],"doctor":["医者なの","医者ですか","カウンセラー","心理士"],"who":["あなたは誰","誰ですか","あなたは人間","ロボット","ボット"],"hello":["こんにちは","こんばんは","おはよう","やあ"],"help":["助けて","どうしたら"],"go":["どこに行","出かけ","何を食べ"],"nowant":["したくない","やめて","ほっといて","いやだ"]}},"help":{"lines":["こころの健康相談統一ダイヤル：0570-064-556","いのちの電話：0120-783-556","救急：119"]}};
